int main(void) {
    // 1. for 루프 (선언, 조건, 증감 통합)
    for (int i = 0; i < 5; i++) {
        if (i == 2) continue; // i=2 회차 스킵
        printf("for i = %d\n", i);
    }

    // 2. while 루프
    int count = 3;
    while (count > 0) {
        printf("while count = %d\n", count--);
    }

    // 3. do-while 루프 (조건 불일치라도 최소 1회 보장)
    int attempt = 0;
    do {
        printf("Executed at least once! attempt=%d\n", attempt);
        attempt++;
    } while (attempt < 0); // 거짓 조건

    return 0;
}

