#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t count = 5;
    // 1. calloc: 0으로 초기화된 메모리 동적 할당
    int *arr = (int *)calloc(count, sizeof(int));
    if (arr == NULL) {
        perror("Allocation failed");
        return 1;
    }

    for (size_t i = 0; i < count; i++) {
        arr[i] = (int)(i + 1) * 10;
    }

    // 2. realloc: 배열 크기를 10개로 확장 (안전 임시 포인터 사용)
    size_t new_count = 10;
    int *temp = (int *)realloc(arr, new_count * sizeof(int));
    if (temp == NULL) {
        free(arr); // realloc 실패 시 원본은 그대로 남아있으므로 누수 방지 해제
        return 1;
    }
    arr = temp;

    printf("arr[4] = %d\n", arr[4]);

    // 3. 안전 해제 패턴
    free(arr);
    arr = NULL; // 댕글링 포인터 방지
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// 연산 콜백 함수들
int op_add(int a, int b) { return a + b; }
int op_multiply(int a, int b) { return a * b; }

// 함수 포인터를 매개변수로 받는 고차 함수
int compute(int x, int y, int (*operation)(int, int)) {
    return operation(x, y);
}

// qsort용 비교 콜백 함수
int compare_ints(const void *a, const void *b) {
    int arg1 = *(const int *)a;
    int arg2 = *(const int *)b;
    return (arg1 > arg2) - (arg1 < arg2); // 오름차순 정렬
}

int main(void) {
    int result1 = compute(5, 3, op_add);
    int result2 = compute(5, 3, op_multiply);
    printf("Add: %d, Mul: %d\n", result1, result2);

    int data[] = {42, 12, 88, 3, 27};
    qsort(data, 5, sizeof(int), compare_ints);
    printf("Sorted: %d, %d, %d, %d, %d\n", data[0], data[1], data[2], data[3], data[4]);
    return 0;
}

