    printf("Buffer size: %zu bytes\n", sizeof(packet));
    printf("Center point: (%d, %d)\n", CENTER.x, CENTER.y);
    return 0;
}

#include <stdio.h>

int main(void) {
    int x = 42;
    typeof(x) y = 100; // y는 int 타입

    const int max_limit = 1000;
    // typeof(max_limit)는 const int이므로 대입 후 수정 불가
    // 반면 typeof_unqual은 const 한정자를 제거하여 순수 int 타입을 얻음
    typeof_unqual(max_limit) modifiable_limit = 500;
    modifiable_limit += 100; // 정상 수정 가능!

    printf("y = %d, modifiable = %d\n", y, modifiable_limit);

    // 복잡한 포인터 타입 보존
    int numbers[] = {1, 2, 3};
    typeof(numbers[0]) *p = &numbers[0]; // int* 타입
    printf("*p = %d\n", *p);
    return 0;
}

