    _BitInt(24) audio_sample = 8388607; // 2^23 - 1 (최댓값)

    // 48비트 부호 없는 정수 (이더넷 MAC 주소, 특수 계수기)
    unsigned _BitInt(48) packet_count = 281474976710655ULL;

    printf("Audio sample: %d (sizeof: %zu bytes)\n", (int)audio_sample, sizeof(audio_sample));
    printf("Packet count: %llu (sizeof: %zu bytes)\n", (unsigned long long)packet_count, sizeof(packet_count));
    return 0;
}

