grammar.example:
#include <stdio.h>

// 반환값을 반드시 수신해야 하는 중요 함수
[[nodiscard]] int send_packet(const char *data) {
    if (!data) return -1;
    return 0; // 성공
}

// 폐기 예정 함수
[[deprecated("Please use modern_compute() instead")]]
int legacy_compute(int x) {
    return x * 2;
}

int main(void) {
    // [[maybe_unused]]로 컴파일러 미사용 경고 억제
    [[maybe_unused]] int cache_line = 64;

    int ret = send_packet("Payload"); // nodiscard 반환값 검사 충족
    printf("Packet result: %d\n", ret);

    int mode = 1;
    switch (mode) {
        case 1:
            printf("Mode 1\n");
            [[fallthrough]]; // 컴파일러에게 의도된 fallthrough임을 통보
        case 2:
            printf("Mode 2\n");
            break;
    }
    return 0;
}

